","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState } from "react";
import { TreeItem } from "../data/treeData";
import "./TreeNode.css";

interface TreeNodeProps {
 key?: string;
 item: TreeItem;
 selectedId: string | null;
 onSelect: (item: TreeItem) => void;
 depth?: number;
}

export default function TreeNode({ item, selectedId, onSelect, depth = 0 }: TreeNodeProps) {
 const [expanded, setExpanded] = useState(true);
 const hasChildren = item.children && item.children.length > 0;
 const isSelected = selectedId === item.id;

 const handleToggle = (e: React.MouseEvent) => {
 e.stopPropagation();
 setExpanded(!expanded);
 };

 const handleSelect = () => {
 onSelect(item);
 };

 return (
 <div className="tree-node" role="treeitem" aria-expanded={hasChildren ? expanded : undefined}>
 <div
 className={`tree-node__row ${isSelected ? "tree-node__row--active" : ""}`}
 style={{ paddingLeft: `${depth * 16 + 8}px` }}
 onClick={handleSelect}
 role="button"
 tabIndex={0}
 onKeyDown={(e) => { if (e.key === "Enter") handleSelect(); }}
 >
 {hasChildren ? (
 <span
 className={`tree-node__toggle ${expanded ? "tree-node__toggle--open" : ""}`}
 onClick={handleToggle}
 role="button"
 tabIndex={0}
 aria-label={expanded ? "Collapse" : "Expand"}
 onKeyDown={(e) => { if (e.key === "Enter") { e.stopPropagation(); setExpanded(!expanded); } }}
 >
 ▶
 </span>
 ) : (
 <span className="tree-node__spacer" />
 )}
 {item.icon && <span className="tree-node__icon">{item.icon}</span>}
 <span className="tree-node__label">{item.label}</span>
 </div>
 {hasChildren && expanded && (
 <div className="tree-node__children" role="group">
 {item.children.map(child => (
 <TreeNode
 key={child.id}
 item={child}
 selectedId={selectedId}
 onSelect={onSelect}
 depth={depth + 1}
 />
 ))}
 </div>
 )}
 </div>
 );
}
