","import React from "react";
import { TreeItem } from "../data/treeData";
import "./ContentPanel.css";

interface ContentPanelProps {
 selectedItem: TreeItem | null;
}

export default function ContentPanel({ selectedItem }: ContentPanelProps) {
 if (!selectedItem || !selectedItem.content) {
 return (
 <div className="content-panel">
 <div className="content-panel__empty">
 <span className="content-panel__empty-icon">📂</span>
 <h2 className="content-panel__empty-title">Select an item</h2>
