 return (
 <div className="content-panel">
 <div className="content-panel__header">
 {selectedItem.icon && (
 <span className="content-panel__header-icon">{selectedItem.icon}</span>
 )}
 <h1 className="content-panel__title">{content.title}</h1>
 </div>
 <p className="content-panel__description">{content.description}</p>
 {content.details && content.details.length > 0 && (
 <div className="content-panel__details">
 <h3 className="content-panel__details-heading">Details</h3>
 <ul className="content-panel__list">
 {content.details.map((detail, index) => (
 <li key={index} className="content-panel__list-item">
 {detail}
 </li>
 ))}
 </ul>
 </div>
 )}
 </div>
 );
}
","import React, { useState, useCallback, useEffect } from "react";
import { TreeItem, treeData } from "./data/treeData";
import TreeView from "./components/TreeView";
import ContentPanel from "./components/ContentPanel";
import "./app.css";

function findItemById(items: TreeItem[], id: string): TreeItem | null {
 for (const item of items) {
 if (item.id === id) return item;
 if (item.children) {
 const found = findItemById(item.children, id);
 if (found) return found;
 }
 }
 return null;
}

function getSelectedFromUrl(): string | null {
 const params = new URLSearchParams(window.location.search);
 return params.get("node") || null;
}

export default function App() {
 const [selectedId, setSelectedId] = useState<string | null>(getSelectedFromUrl);
 const selectedItem = selectedId ? findItemById(treeData, selectedId) : null;

 useEffect(() => {
 const onPopState = () => setSelectedId(getSelectedFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const handleSelect = useCallback((item: TreeItem) => {
 const params = new URLSearchParams({ node: item.id });
 const relativePath = `${window.location.pathname}?${params}`;
 const pageTitle = `Tree Navigator - ${item.label}`;

 if (window.self !== window.top) {
 (window as any).CustomEvent.fireTop("magellanNavigator.permalink.set", {
 relativePath,
 title: pageTitle
 });
 }

 window.history.pushState({ node: item.id }, "", relativePath);
 document.title = pageTitle;
 setSelectedId(item.id);
 }, []);

 return (
 <div className="app-layout">
 <aside className="app-layout__sidebar">
 <TreeView
 items={treeData}
 selectedId={selectedId}
 onSelect={handleSelect}
 />
 </aside>
 <main className="app-layout__content">
 <ContentPanel selectedItem={selectedItem} />
 </main>
 </div>
 );
}
",".tree-node__row {
 display: flex;
 align-items: center;
 gap: 6px;
 padding: 6px 8px;
 cursor: pointer;
 border-radius: 4px;
 transition: background-color 0.15s ease;
 user-select: none;
 min-height: 32px;
}

.tree-node__row:hover {
 background-color: var(--now-color-background-secondary, rgba(0, 0, 0, 0.04));
}

.tree-node__row--active {
 background-color: var(--now-color-background-highlight, rgba(0, 128, 163, 0.08));
 color: var(--now-color-text-brand, #0078a5);
}

.tree-node__row--active:hover {
 background-color: var(--now-color-background-highlight, rgba(0, 128, 163, 0.12));
}

.tree-node__toggle {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 width: 18px;
 height: 18px;
 font-size: 9px;
 color: var(--now-color-text-tertiary, #6b7280);
 transition: transform 0.2s ease;
 flex-shrink: 0;
 border-radius: 3px;
}

.tree-node__toggle:hover {
 background-color: var(--now-color-background-tertiary, rgba(0, 0, 0, 0.06));
}

.tree-node__toggle--open {
 transform: rotate(90deg);
}

.tree-node__spacer {
 display: inline-block;
 width: 18px;
 flex-shrink: 0;
}

.tree-node__icon {
 font-size: 14px;
 flex-shrink: 0;
}

.tree-node__label {
 font-size: 13px;
 line-height: 1.4;
 white-space: nowrap;
 overflow: hidden;
 text-overflow: ellipsis;
 color: var(--now-color-text-primary, #1f2937);
}

.tree-node__row--active .tree-node__label {
 font-weight: 500;
}

.tree-node__children {
 overflow: hidden;
}
",".tree-view {
 display: flex;
 flex-direction: column;
 height: 100%;
 overflow: hidden;
}

.tree-view__header {
 display: flex;
 align-items: center;
 padding: 16px 16px 12px;
 border-bottom: 1px solid var(--now-color-border-primary, #e5e7eb);
}

.tree-view__title {
 font-size: 14px;
 font-weight: 600;
 color: var(--now-color-text-primary, #1f2937);
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

.tree-view__content {
 flex: 1;
 overflow-y: auto;
 padding: 8px;
}
",".content-panel {
 padding: 32px;
 height: 100%;
 overflow-y: auto;
}

.content-panel__empty {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 height: 100%;
 text-align: center;
 gap: 12px;
}

.content-panel__empty-icon {
 font-size: 48px;
 opacity: 0.6;
}

.content-panel__empty-title {
 font-size: 20px;
 font-weight: 600;
 color: var(--now-color-text-primary, #1f2937);
 margin: 0;
}

.content-panel__empty-text {
 font-size: 14px;
 color: var(--now-color-text-secondary, #6b7280);
 max-width: 320px;
 margin: 0;
}

.content-panel__header {
 display: flex;
 align-items: center;
 gap: 12px;
 margin-bottom: 16px;
}

.content-panel__header-icon {
 font-size: 28px;
}

.content-panel__title {
 font-size: 24px;
 font-weight: 600;
 color: var(--now-color-text-primary, #1f2937);
 margin: 0;
}

.content-panel__description {
 font-size: 15px;
 line-height: 1.6;
 color: var(--now-color-text-secondary, #4b5563);
 margin: 0 0 24px;
}

.content-panel__details {
 background-color: var(--now-color-background-secondary, #f9fafb);
